import subprocess, os
def run(args, cwd="/tmp", env=None):
    e=dict(os.environ)
    if env: e.update(env)
    return subprocess.run(["/workspace/executable"]+args, capture_output=True, text=True, cwd=cwd, env=e)
def show(label, args, **kw):
    p=run(args, **kw)
    print(f"=== {label} :: {args} exit={p.returncode}")
