import subprocess, os, shutil
def build(spec, base):
    if os.path.exists(base): shutil.rmtree(base)
    os.makedirs(base)
    # spec nested dict: name->dict for dir, or size int for file
    def rec(s, path):
        for name, val in s.items():
            p=os.path.join(path,name)
            if isinstance(val, dict):
                os.makedirs(p); rec(val,p)
            else:
                open(p,"wb").write(b"x"*val)
    rec(spec, base)
def index(base, db):
    try: os.remove(db)
    except: pass
    subprocess.run(["/workspace/executable","index",base,"-d",db],capture_output=True)
def ls(db, base, extra=[]):
    p=subprocess.run(["/workspace/executable","ls","-R"]+extra+["-d",db,base],capture_output=True,text=True)
