# ---------------- database ----------------
DB_MAGIC = b"PYDUC1\x00"
class DBError(Exception):
    def __init__(self, msg, path_none=False):
        super().__init__(msg)
        self.msg = msg; self.path_none = path_none
    def second(self):
        if self.msg in (b"Database not found", b"Database corrupt and not usable"):
            return self.msg
        return b"No error: success"

def _db_str(path):
    return os.fsdecode(path)

def _connect(path):
    return sqlite3.connect(_db_str(path))

def _read_blobs(con):
    reports = []; histograms = []; root_records = {}; dir_records = {}
    try:
        tables = [r[0] for r in con.execute("select name from sqlite_master where type in ('table','index')")]
    except sqlite3.Error:
        raise DBError(b"Database corrupt and not usable")
    if "blobs" not in tables:
        return reports, histograms, root_records, dir_records
    try:
        rows = list(con.execute("select key, value from blobs"))
    except sqlite3.Error:
        raise DBError(b"Database corrupt and not usable")
    for key, value in rows:
        if isinstance(key, str): key = key.encode()
        if isinstance(value, str): value = value.encode('utf-8', 'ignore')
        if value is None or not isinstance(value, (bytes, bytearray)) or not bytes(value).startswith(DB_MAGIC):
            continue
        try:
            obj = pickle.loads(bytes(value)[len(DB_MAGIC):])
        except Exception:
            continue
        if key == b"duc_index_reports":
            reports = obj
        elif key == b"duc_index_histograms":
            histograms = obj
        elif key.startswith(b"/"):
            root_records[key] = obj
        else:
            dir_records[key] = obj
    return reports, histograms, root_records, dir_records

class DucDB:
    def __init__(self):
        self.reports = []; self.histograms = []; self.root_records = {}; self.dir_records = {}
        self.con = None

def open_db_read(path):
    if path is None:
        raise DBError(b"Database not found", path_none=True)
    if path == b"":
        raise DBError(b"unsupported DB type _unknown_, duc compiled for sqlite3")
    if not os.path.exists(path):
        raise DBError(b"Database not found")
    if os.path.isdir(path):
        raise DBError(b"Database corrupt and not usable")
    try:
        if os.path.getsize(path) < 2:
            raise DBError(b"unsupported DB type _unknown_, duc compiled for sqlite3")
    except DBError:
        raise
    except Exception:
        raise DBError(b"Database not found")
    try:
        con = _connect(path)
        # force schema parse
        list(con.execute("select name from sqlite_master limit 1"))
    except DBError:
        raise
    except Exception:
        raise DBError(b"Database corrupt and not usable")
