# ---------------- indexing ----------------
class ScanState:
    def __init__(self, opts):
        self.file_count = 0; self.dir_count = 0
        self.total_apparent = 0; self.total_actual = 0
        self.num_buckets = opts["buckets"]
        nb = self.num_buckets if self.num_buckets > 0 else 0
        self.histogram = [0] * nb
        self.excludes = opts["exclude"]
        self.hide = opts["hide_file_names"]
        self.check_hard = opts["check_hard_links"]
        self.seen_inodes = set()
        self.max_depth = opts["max_depth"]
        self.one_fs = opts["one_file_system"]
        self.fs_exclude = []
        self.fs_include = []
        for raw in opts["fs_exclude"]:
            for item in raw.split(b","): self.fs_exclude.append(item)
        for raw in opts["fs_include"]:
            for item in raw.split(b","): self.fs_include.append(item)
        # uid filter
        self.uid_filter = None
        if opts.get("_uid_set") and opts.get("uid", 0) != 0:
            self.uid_filter = opts["uid"]
        elif opts.get("_username_set"):
            self.uid_filter = opts["_username_uid"]
        self.progress = opts["progress"]
        self.root_dev = None
        self.pending_root = {}; self.pending_dirs = {}
        self.start = time.time()

def type_char(mode):
    if stat.S_ISDIR(mode): return 47  # /
    if stat.S_ISLNK(mode): return ord('>')
    if stat.S_ISFIFO(mode): return ord('|')
    if stat.S_ISSOCK(mode): return ord('@')
    return ord(' ')

def scan_dir(state, fs_path, debug_name, depth, is_root, cur_dev, cur_ino):
    try:
        it = os.scandir(fs_path)
        entries_list = list(it)
        try: it.close()
        except Exception: pass
    except OSError as e:
        msg = e.strerror if e.strerror else str(e)
        LOG.warn(b"skipping " + fs_path + b": " + msg.encode('utf-8', 'surrogateescape'))
        return None
    state.dir_count += 1
    if state.progress and state.dir_count == 102 and not PROG.triggered102:
        PROG.triggered102 = True
        progress_print(state, final=False)
    LOG.debug(b">> " + debug_name)
    agg_app = 0; agg_act = 0; agg_cnt = 1
    record_entries = []
    for dent in entries_list:
        name = dent.name
        child_path = join_path(fs_path, name)
        try:
            st = dent.stat(follow_symlinks=False)
        except OSError as e:
            msg = e.strerror if e.strerror else str(e)
            LOG.warn(b"skipping " + child_path + b": " + msg.encode('utf-8', 'surrogateescape'))
            continue
        excluded = False
        for pat in state.excludes:
            if fnmatch.fnmatchcase(name, pat):
                excluded = True; break
        if excluded:
            LOG.warn(b"skipping " + child_path + b": Excluded by user")
            continue
        if state.uid_filter is not None and st.st_uid != state.uid_filter:
            continue
        tc = type_char(st.st_mode)
        if stat.S_ISDIR(st.st_mode):
            if state.one_fs and state.root_dev is not None and st.st_dev != state.root_dev:
                continue
            if st.st_dev != cur_dev:
                fst = fs_type_for_path(child_path)
                if fst in state.fs_exclude:
                    continue
                if state.fs_include and fst not in state.fs_include:
                    continue
            child = scan_dir(state, child_path, name, depth + 1, False, st.st_dev, st.st_ino)
            if child is None:
                continue
            agg_app += child["app"]; agg_act += child["act"]; agg_cnt += child["cnt"]
            if state.max_depth == 0 or (depth + 1) <= state.max_depth:
                record_entries.append({"n": name, "t": 47, "app": child["app"], "act": child["act"], "cnt": child["cnt"], "dev": st.st_dev, "ino": st.st_ino})
        else:
            if state.check_hard and st.st_nlink > 1:
                key = (st.st_dev, st.st_ino)
                if key in state.seen_inodes:
                    continue
                state.seen_inodes.add(key)
            state.file_count += 1
            app = st.st_size
            act = (st.st_blocks * 512) if hasattr(st, "st_blocks") else 0
            # histogram (apparent size)
            if app <= 1: bucket = 0
            else: bucket = app.bit_length() - 1
            if bucket >= state.num_buckets:
                LOG.warn(b"File sizes large enough we ran out of histogram buckets " + str(state.num_buckets).encode() + b", please increase the number of buckets and re-run your indexing.")
            else:
                state.histogram[bucket] += 1
            agg_app += app; agg_act += act; agg_cnt += 1
