# ---------------- info / histogram / topn ----------------

def open_read_or_error(opts, with_second):
    dbpath = resolve_database(opts)
    LOG.info(b"Reading from database \"" + (dbpath if dbpath is not None else b"") + b"\"")
    try:
        db = open_db_read(dbpath)
        return db, dbpath, 0
    except DBError as e:
        db_open_error_handling(e, dbpath, with_second)
        return None, dbpath, 1

def format_report_date(ts):
    lt = time.localtime(ts)
    return time.strftime("%Y-%m-%d", lt).encode(), time.strftime("%H:%M:%S", lt).encode()

def cmd_info(opts, args, prog):
    db, dbpath, rc = open_read_or_error(opts, True)
    if db is None: return rc
    out = []
    out.append(b"Date       Time       Files    Dirs    Size Path\n")
    for idx, rep in enumerate(db.reports):
        date_b, time_b = format_report_date(rep["time"])
        val = rep["app"] if opts["apparent"] else rep["act"]
        size_s = str(val).encode() if opts["bytes"] else fmt_human(val).encode()
        out.append(date_b + b" " + time_b + b" " + ("%7d" % rep["files"]).encode() + b" " + ("%7d" % rep["dirs"]).encode() + b" " + ("%7s" % size_s.decode('utf-8','surrogateescape')).encode('utf-8','surrogateescape') + b" " + rep["path"] + b"\n")
        if opts["histogram"]:
            out.append(b"\nHistogram:\n----------\n")
            hist = db.histograms[idx] if idx < len(db.histograms) else []
            for bidx, cnt in enumerate(hist):
                if cnt:
                    out.append(b"2^" + ("%-4d" % bidx).encode() + str(cnt).encode() + b"\n")
    out_b(b"".join(out))
    return 0

def cmd_histogram(opts, args, prog):
    db, dbpath, rc = open_read_or_error(opts, True)
    if db is None: return rc
    out = []
    for idx, rep in enumerate(db.reports):
        out.append(b"Path: " + rep["path"] + b"\n")
        out.append(b"Bkt       Size      Count\n")
