def graph_hit(db, root_record, root_canon, opts, x, y):
    """Return ('dir', path, entry, record) / ('file', path, entry, None) / ('center',None,None,None) / None"""
    size = opts.get("size", 800); levels = opts.get("levels", 4)
    if levels <= 0: return None
    center = size // 2; bounds = graph_boundaries(size, levels)
    dx = x - center; dy = y - center; r = math.hypot(dx, dy)
    if r < bounds[0]: return ("center", root_canon, None, root_record)
