        if total <= 0: return None
        entries = sorted_entries(record["entries"], apparent, count_mode, False)
        cur = 0.0; found = None
        for e in entries:
            v = entry_value(e, apparent, count_mode)
            w = 1000.0 * v / total if v else 0.0
            if v and cur <= milli < cur + w or (v and milli == 1000 and cur + w >= 1000):
                found = e; break
            cur += w
        if found is None: return None
        child_path = join_path(path_prefix, found["n"])
        if found["t"] != 47:
            return ("file", child_path, found, None)
        # directory: if radius is within this entry's ring, return it
        if depth + 1 >= len(bounds) or r < bounds[depth + 1]:
            child_rec = db.dir_records.get(("%x/%x" % (found["dev"], found["ino"])).encode())
            return ("dir", child_path, found, child_rec)
        child_rec = db.dir_records.get(("%x/%x" % (found["dev"], found["ino"])).encode())
        if child_rec is None:
            return ("dir", child_path, found, None)
        record = child_rec; depth += 1; path_prefix = child_path

def cmd_graph(opts, args, prog):
