            a1 = cur; a2 = cur + span * v / total; cur = a2
            if depth >= levels: continue
            r_in = bounds[depth]; r_out_full = bounds[depth+1] - ring_gap
            r_out = r_out_full
            if v < max_val and fuzz:
                step = bounds[depth+1] - bounds[depth]
                r_out = _round_half_even(r_out_full - fuzz * step)
            child_rec = None; child_path = join_path(path_prefix, e["n"]) if path_prefix else e["n"]
            seg = Seg(); seg.a1 = a1; seg.a2 = a2; seg.r1 = r_in; seg.r2 = r_out; seg.depth = depth
            seg.entry = e; seg.name = e["n"]; seg.path = child_path; seg.record = None
            mid_deg = ((a1 + a2) / 2.0) / 1000.0 * 360.0
            seg.color = palette_color(palette, mid_deg, depth, seg)
            seg.mid_deg = mid_deg
            if e["t"] == 47:
                child_rec = db.dir_records.get(("%x/%x" % (e["dev"], e["ino"])).encode())
                seg.record = child_rec
                if child_rec is not None and depth < levels - 1:
                    draw_dir(child_rec, a1, a2, depth + 1, child_path)
            segs.append(seg)
    draw_dir(root_record, 0.0, 1000.0, 0, root_canon)
    # labels in segment order
    for seg in segs:
        if seg.a2 - seg.a1 < 20: continue
        mid_milli = (seg.a1 + seg.a2) / 2.0
        theta = mid_milli / 1000.0 * 2 * math.pi - math.pi / 2
        rmid = (seg.r1 + seg.r2) / 2.0
        x = _round_half_even(center + rmid * math.cos(theta)); y = _round_half_even(center + rmid * math.sin(theta))
        val = entry_value(seg.entry, apparent, count_mode)
        size_label = str(val).encode() if count_mode else fmt_human(val).encode()
        labels.append((seg.name + b"\n" + size_label, x, y, 8))
    app, act, cnt = dir_totals(root_record)
    total_val = cnt if count_mode else (app if apparent else act)
    total_label = str(total_val).encode() if count_mode else fmt_human(total_val).encode()
    labels.append((original, center, 10, 8))
    labels.append((total_label, center, center, 14))
    return segs, labels

def _seg_points(seg, center):
    def pt(r, milli):
        th = milli / 1000.0 * 2 * math.pi - math.pi / 2
        return (_round_half_even(center + r * math.cos(th)), _round_half_even(center + r * math.sin(th)))
    return pt(seg.r1, seg.a1), pt(seg.r2, seg.a1), pt(seg.r2, seg.a2), pt(seg.r1, seg.a2)

def render_svg(db, root_record, root_canon, original, opts):
    size = opts.get("size", 800); center = size // 2
    segs, labels = build_segments(db, root_record, root_canon, original, opts)
    out = []
    out.append(b"<?xml version='1.0' standalone='no'?>\n")
    out.append(b"<!DOCTYPE svg PUBLIC '-//W3C//DTD SVG 1.1//EN' \n 'http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd'>\n")
    out.append(b"<svg width='" + str(size).encode() + b"px' height='" + str(size).encode() + b"px'\n     xmlns='http://www.w3.org/2000/svg'\n     xmlns:xlink='http://www.w3.org/1999/xlink'>\n")
    out.append(b" <style><![CDATA[\n    text {\n      font-family: 'Arial';\n      text-anchor: middle;\n      dominant-baseline: middle;\n    }\n    radialGradient {\n      gradientUnits: userSpaceOnUse;\n    }\n  ]]>\n</style>\n")
    gradient = opts.get("gradient", False)
    for idx, seg in enumerate(segs):
        p1, p2, p3, p4 = _seg_points(seg, center)
        large = 1 if (seg.a2 - seg.a1) > 500 else 0
        d = ("M%d,%d L%d,%d A %d %d 0 %d 1 %d %d L%d,%d A %d %d 0 %d 0 %d,%d " % (p1[0], p1[1], p2[0], p2[1], seg.r2, seg.r2, large, p3[0], p3[1], p4[0], p4[1], seg.r1, seg.r1, large, p1[0], p1[1])).encode()
        col = seg.color; hexcol = ("#%02x%02x%02x" % col).encode()
        if gradient:
            dark = tuple(int(round(c * 0.61)) for c in col)
            off = (seg.r1 / seg.r2 * 100.0) if seg.r2 else 0.0
            out.append(b"<defs>\n <radialGradient gradientUnits='userSpaceOnUse' id='g" + str(idx).encode() + b"' cx='" + str(center).encode() + b"' cy='" + str(center).encode() + b"' r='" + str(seg.r2).encode() + b"'>\n")
            out.append(b"  <stop offset='" + ("%.1f%%" % off).encode() + b"' style='stop-color:" + ("#%02x%02x%02x" % dark).encode() + b";'/>\n")
            out.append(b"  <stop offset='100%' style='stop-color:" + hexcol + b";'/>\n </radialGradient>\n</defs>\n")
            fill = b"url(#g" + str(idx).encode() + b")"
        else:
            fill = hexcol
        out.append(b"<path fill='" + fill + b"' d='" + d + b"'/>\n")
    for text, x, y, fontsize in labels:
        lines = text.split(b"\n")
        for style_attrs in [b"stroke='white' stroke-width='3' stroke-opacity='0.7'", b"fill='black'"]:
            out.append(b"<text x='" + str(x).encode() + b"' y='" + str(y).encode() + b"' font-size='" + str(fontsize).encode() + b"pt' " + style_attrs + b">\n")
            for li, ln in enumerate(lines):
                dy = b"0.0em" if li == 0 else b"1.2em"
                out.append(b" <tspan x='" + str(x).encode() + b"' dy='" + dy + b"'>" + xml_escape(ln) + b"</tspan>\n")
            out.append(b"</text>\n")
    out.append(b"</svg>\n")
