def js_escape(b):
    b = b.replace(b"\\", b"\\\\"); b = b.replace(b"'", b"\\'"); b = b.replace(b"\n", b"\\n"); b = b.replace(b"\t", b"\\t"); b = b.replace(b"\r", b"\\r")
    return b

