def render_html_canvas(db, root_record, root_canon, original, opts, center_override=None):
    size = opts.get("size", 800)
    segs, labels = build_segments(db, root_record, root_canon, original, opts)
    center = size // 2
    # The canvas script in the original always draws around (400,400) for size 800;
    # it scales in the function using the fixed centre of the configured size.
    head = HTML_CANVAS_SCRIPT_HEAD % (size, size)
    # replace centre in g()/t() helpers when size differs: original uses size/2 in arc calls
    # (the literal 400 above is the 800-default; adjust by textual replacement of arc centre)
    if center != 400:
        head = head.replace(b"c.arc(400, 400,", b"c.arc(" + str(center).encode() + b", " + str(center).encode() + b",")
    out = [head]
    pal = (opts.get("palette", b"size") or b"size").lower()
    line_par = 204 if pal == b"classic" else (2 if pal == b"monochrome" else 0)
    for seg in segs:
        r, g, b = seg.color
        out.append(b"g(%d,%d,%d,%d,%d,%d,%d,%d);\n" % (int(seg.a1), int(seg.a2), int(seg.r1), int(seg.r2), r, g, b, line_par))
    for text, x, y, fontsize in labels:
        out.append(b"t('" + js_escape(text) + b"',%d,%d,%d);\n" % (fontsize, x, y))
    out.append(b"</script>\n")
    return b"".join(out)

def render_html(db, root_record, root_canon, original, opts):
    size = opts.get("size", 800)
    out = []
    out.append(b"<?xml version='1.0' standalone='no'?>\n")
    out.append(b"<!DOCTYPE html PUBLIC '-//W3C//DTD SVG 1.1//EN' \n 'http://www.w3.org/Graphics/SVG/1.1/DTD/html11.dtd'>\n")
    out.append(b"<html xmlns='http://www.w3.org/2000/html' xmlns:xlink= 'http://www.w3.org/1999/xlink'>\n")
    out.append(render_html_canvas(db, root_record, root_canon, original, opts))
    out.append(b"</html>\n")
    return b"".join(out)

def render_png(db, root_record, root_canon, original, opts):
    size = opts.get("size", 800)
    if size <= 0: size = 1
    if size > 4096: size = 4096
    segs, labels = build_segments(db, root_record, root_canon, original, opts)
    center = size // 2
    # RGBA buffer, transparent background
    buf = bytearray(size * size * 4)
    for seg in segs:
        rcol, gcol, bcol = seg.color
        # bounding box
        rmax = max(abs(seg.r1), abs(seg.r2))
        x0 = max(0, center - rmax - 1); x1 = min(size - 1, center + rmax + 1)
        y0 = max(0, center - rmax - 1); y1 = min(size - 1, center + rmax + 1)
        for yy in range(y0, y1 + 1):
            dy = yy - center
            for xx in range(x0, x1 + 1):
                dx = xx - center
                rr = math.hypot(dx, dy)
                if rr < min(seg.r1, seg.r2) or rr > max(seg.r1, seg.r2): continue
                ang = (math.atan2(dy, dx) + math.pi / 2) % (2 * math.pi)
                milli = ang / (2 * math.pi) * 1000.0
                if seg.a1 <= milli <= seg.a2 or (seg.a2 >= 1000 and milli >= seg.a1):
                    off = (yy * size + xx) * 4
                    buf[off] = rcol; buf[off+1] = gcol; buf[off+2] = bcol; buf[off+3] = 255
    raw = bytearray()
    rowlen = size * 4
    for yy in range(size):
        raw.append(0); raw += buf[yy*rowlen:(yy+1)*rowlen]
    def chunk(typ, data):
        c = struct.pack(">I", len(data)) + typ + data
        c += struct.pack(">I", zlib.crc32(typ + data) & 0xffffffff)
        return c
    png = bytearray(b"\x89PNG\r\n\x1a\n")
    png += chunk(b"IHDR", struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0))
    png += chunk(b"IDAT", zlib.compress(bytes(raw), 6))
    png += chunk(b"IEND", b"")
    return bytes(png)

def render_pdf(db, root_record, root_canon, original, opts):
    size = opts.get("size", 800)
    if size <= 0: size = 800
    segs, labels = build_segments(db, root_record, root_canon, original, opts)
    center = size // 2
    content = []
    for seg in segs:
        r, g, b = seg.color
        content.append(("%.3f %.3f %.3f rg\n" % (r/255.0, g/255.0, b/255.0)).encode())
        # polygon approximation
        steps = max(2, int((seg.a2 - seg.a1) / 10) + 1)
        pts = []
        for i in range(steps + 1):
            milli = seg.a1 + (seg.a2 - seg.a1) * i / steps
            th = milli / 1000.0 * 2 * math.pi - math.pi / 2
            pts.append((center + seg.r2 * math.cos(th), size - (center + seg.r2 * math.sin(th))))
        for i in range(steps, -1, -1):
            milli = seg.a1 + (seg.a2 - seg.a1) * i / steps
            th = milli / 1000.0 * 2 * math.pi - math.pi / 2
            pts.append((center + seg.r1 * math.cos(th), size - (center + seg.r1 * math.sin(th))))
        if pts:
            content.append(("%.2f %.2f m\n" % pts[0]).encode())
            for x, y in pts[1:]: content.append(("%.2f %.2f l\n" % (x, y)).encode())
            content.append(b"h f\n")
    stream = b"".join(content)
    objs = []
    objs.append(b"<< /Type /Catalog /Pages 2 0 R >>")
    objs.append(b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>")
    objs.append(("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 %d %d] /Contents 4 0 R /Resources << >> >>" % (size, size)).encode())
    objs.append(b"<< /Length " + str(len(stream)).encode() + b" >>\nstream\n" + stream + b"endstream")
    pdf = bytearray(b"%PDF-1.4\n")
    offsets = []
    for i, obj in enumerate(objs, start=1):
        offsets.append(len(pdf)); pdf += ("%d 0 obj\n" % i).encode(); pdf += obj; pdf += b"\nendobj\n"
    xref = len(pdf)
    pdf += ("xref\n0 %d\n" % (len(objs)+1)).encode()
    pdf += b"0000000000 65535 f \n"
    for off in offsets: pdf += ("%010d 00000 n \n" % off).encode()
    pdf += ("trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (len(objs)+1, xref)).encode()
    return bytes(pdf)

def graph_hit(db, root_record, root_canon, opts, x, y):
    """Return ('dir', path, entry, record) / ('file', path, entry, None) / ('center',None,None,None) / None"""
    size = opts.get("size", 800); levels = opts.get("levels", 4)
    if levels <= 0: return None
    center = size // 2; bounds = graph_boundaries(size, levels)
    dx = x - center; dy = y - center; r = math.hypot(dx, dy)
    if r < bounds[0]: return ("center", root_canon, None, root_record)
    if r > bounds[levels]: return None
    apparent = opts.get("apparent", False); count_mode = opts.get("count", False)
    ang = (math.atan2(dy, dx) + math.pi / 2) % (2 * math.pi)
    milli = ang / (2 * math.pi) * 1000.0
    record = root_record; depth = 0; path_prefix = root_canon
    while True:
        total = sum(entry_value(e, apparent, count_mode) for e in record["entries"])
        if total <= 0: return None
        entries = sorted_entries(record["entries"], apparent, count_mode, False)
        cur = 0.0; found = None
        for e in entries:
            v = entry_value(e, apparent, count_mode)
            w = 1000.0 * v / total if v else 0.0
            if v and cur <= milli < cur + w or (v and milli == 1000 and cur + w >= 1000):
                found = e; break
            cur += w
        if found is None: return None
        child_path = join_path(path_prefix, found["n"])
        if found["t"] != 47:
            return ("file", child_path, found, None)
        # directory: if radius is within this entry's ring, return it
        if depth + 1 >= len(bounds) or r < bounds[depth + 1]:
            child_rec = db.dir_records.get(("%x/%x" % (found["dev"], found["ino"])).encode())
            return ("dir", child_path, found, child_rec)
        child_rec = db.dir_records.get(("%x/%x" % (found["dev"], found["ino"])).encode())
        if child_rec is None:
            return ("dir", child_path, found, None)
        record = child_rec; depth += 1; path_prefix = child_path

def cmd_graph(opts, args, prog):
    db, dbpath, rc = open_read_or_error(opts, True)
    if db is None: return rc
    original = args[0] if args else b"."
    record = lookup_dir(db, original)
    if record is None:
        LOG.error(b"Requested path not found")
        return 1
    canon = canonical_path(original)
    fmt = (opts["format"] or b"png").lower()
    if fmt == b"svg": data = render_svg(db, record, canon, original, opts)
    elif fmt == b"pdf": data = render_pdf(db, record, canon, original, opts)
    elif fmt == b"html": data = render_html(db, record, canon, original, opts)
    else: data = render_png(db, record, canon, original, opts)
    outpath = opts["output"]
    if outpath == b"-":
        out_b(data); return 0
    try:
        with open(outpath, "wb") as f: f.write(data)
    except OSError as e:
        err_b(b"Error opening output file: " + (e.strerror or str(e)).encode() + b"\n")
        return 1
    return 0

