def url_decode(b):
    if b is None: return b""
    out = bytearray(); i = 0
    while i < len(b):
        c = b[i]
        if c == 0x2b:  # +
            out.append(0x20); i += 1
        elif c == 0x25 and i + 2 < len(b):
            try:
                out.append(int(b[i+1:i+3], 16)); i += 3
            except Exception:
                out.append(c); i += 1
        else:
